/**
 * One retailer's row in a /match/* answer.
 *
 * Mirrors `ProductMatch.to_dict()` field for field: a response model drops
 * every key it does not declare, so a field added there and not here would
 * vanish from the API without an error (`test_match_rijschema.py`).
 */
export interface MatchRow {
  /** Answerable via /api/v1/products/{id}, or null: a shelf row whose SKU has no live product carries no id rather than one that 404s. */
  product_id?: string | null;
  /** Product name as the retailer states it */
  name: string;
  /** Brand, when stated */
  brand?: string | null;
  /** EUR. The promotion price on an active/upcoming row, the regular price on a shelf/historical row. */
  price: number;
  /** Regular price next to a promotion price, when known */
  original_price?: number | null;
  /** Retailer slug */
  retailer: string;
  /** Retailer name for display */
  retailer_display: string;
  /** Rounded discount derived from price and original_price */
  savings_percentage?: number | null;
  /** True on an `active` row only. A shelf price is payable today but is not a deal. */
  is_current_deal: boolean;
  /** EAN/GTIN of this row */
  ean?: string | null;
  /** The retailer's product page */
  url?: string | null;
  /** How the row was found. `exact_ean`: same barcode (every row on /match/ean). `fuzzy_text`: an approximation on name, brand and pack, returned only by /match/product. Build on this field to tell an exact match from an approximation. */
  match_level: string;
  /** A RANK per source, not a per-row score and not a probability: 0.98 live promotion on EAN, 0.95 shelf price on EAN, 0.90 recent observation on EAN, 0.80 another chain's house brand, 0.60 a match on name or on brand and name, 0.50 the name search that fills chains below three barcode matches. The order follows measured precision per picked row (house brand 99%, name and brand 93-96%, the name search far below that), so it orders sources. Do not threshold on it and do not read it as a chance. */
  confidence: number;
  /** The retailer's promotion label, e.g. '1+1 gratis' */
  promotion?: string | null;
  /** `active`, `upcoming`, `shelf` (current regular price) or `historical` (most recent price seen in the last 60 days). */
  promotion_status?: string | null;
  /** Promotion start (ISO date) */
  valid_from?: string | null;
  /** Promotion end (ISO date) */
  valid_until?: string | null;
  /** True when valid_until is OUR rolling estimate, not a date the retailer published (today only PLUS long-running promotions), false when the retailer stated it. Null means not assessed, which is every shelf and historical row: those carry no promotion window. */
  valid_until_estimated?: boolean | null;
  /** Price per unit */
  unit_price?: number | null;
  /** Unit of unit_price: kg, L or stuk */
  unit?: string | null;
  /** Pack size as the retailer states it. A GTIN does not identify a pack size, so read every price next to it. */
  quantity?: string | null;
  /** On a shelf/historical row: the most recent promotion price seen for this retailer and pack in the last 60 days */
  last_deal_price?: number | null;
  /** Last day of that promotion (ISO date) */
  last_deal_until?: string | null;
  /** Shelf rows only: since when this regular price has held, ISO 8601 with offset */
  price_changed_at?: string | null;
  /** True marks an approximation, never the same product: a match on name and pack size (at a chain that publishes no barcode), on brand, name and pack, another chain's house brand, or the name search that fills chains below three barcode matches. Every row that is not an exact barcode match carries it, so `approx == false` is the same set as `match_level == "exact_ean"`. Only on /match/product; always false on /match/ean. */
  approx: boolean;
  /** True marks another chain's own house brand under the same name and pack (always with approx=true). Only on /match/product. */
  private_label_equivalent: boolean;
}
